def _set_parent(self, parent=None):
        """
        Set parent.

        :param parent: Parentable object.
        :raises ValueError: Self-reference object passed.
        :raises ValueError: Non-Parentable object passed.
        """
            if parent is not None and not isinstance(parent, Parentable):
                raise ValueError(
                    "Non-Parentable object passed. "
                    "Expected Parentable object."
                )
            if parent is not None and parent is self:
                raise ValueError(
                    "Self-reference object passed. "
                    "Expected non-self reference."
                )
            self._parent = parent

